-- CCN Mock Exam Day 8 (30 Oct 2026): the hardest paper — 200 questions, 10 sections of 20.
-- A ventilator (parts, set-up, modes, parameters, alarms) · B ICU machines (syringe pumps, monitors, defibrillator,
-- arterial lines, chest drains, CRRT, oxygen devices) · C–G identify the disease from signs and symptoms
-- (cardiovascular, respiratory, neurological, renal/electrolytes/acid–base, endocrine/GI/liver) · H multi-organ
-- failure, shock, trauma, burns, poisoning · I obstetric, neonatal, paediatric · J pharmacology, anaesthesia,
-- professional practice.
-- Adds the questions as hidden exam-only copies (not shown in the practice app) and creates the exam
-- (open now until 11:00 PM tonight, 200 minutes, 1 attempt, answers hidden, score shown).
-- If the exam already exists, only its questions are updated. Safe to run more than once.
set lock_timeout = '5s';
begin;
create temporary table d8new (n int primary key, topic text, q text, opts jsonb, ans_idx int, exp text, category text) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + d.n, d.topic, 'CCN Mock Exam — Day 8 (30 Oct 2026)', d.q, d.opts, d.ans_idx, d.exp, d.category, '📝', false
from d8new d
where not exists (select 1 from public.questions x where x.source = 'CCN Mock Exam — Day 8 (30 Oct 2026)' and x.q = d.q);
update public.exam_exams
   set question_ids = (select array_agg(x.id order by d.n) from d8new d join public.questions x on x.source = 'CCN Mock Exam — Day 8 (30 Oct 2026)' and x.q = d.q)
 where title = 'CCN Mock Exam — Day 8: Hardest Paper (200 Questions)';
                               show_answers, show_score, max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level)
select 'CCN Mock Exam — Day 8: Hardest Paper (200 Questions)',
       'Day 8 — the hardest paper. 200 questions across the whole CCN curriculum: ventilators, ICU machines, identifying diseases from signs and symptoms in every organ system, multi-organ failure, obstetrics and paediatrics, pharmacology and professional practice. The options are deliberately similar: read every option before you choose. Choose the ONE best answer. Each correct answer carries 1 mark. You have 200 minutes.',
       now(), timestamptz '2026-10-30 23:00:00+01', 200,
       (select array_agg(x.id order by d.n) from d8new d join public.questions x on x.source = 'CCN Mock Exam — Day 8 (30 Oct 2026)' and x.q = d.q),
       false, true, 100, true, true, 1, 'relaxed'
where not exists (select 1 from public.exam_exams where title = 'CCN Mock Exam — Day 8: Hardest Paper (200 Questions)');
select title, cardinality(question_ids) as questions_in_exam, starts_at, ends_at from public.exam_exams where title = 'CCN Mock Exam — Day 8: Hardest Paper (200 Questions)';
commit;
